import { Box, Grid, Paper, Tooltip, TextField, InputAdornment, Collapse, IconButton, ButtonGroup, Button, CircularProgress, Menu, MenuItem, Typography } from "@mui/material";
import './styles.scss';
import { useOutletContext, useSearchParams } from "react-router-dom";
import Divider from '@mui/material/Divider';
import React, { SyntheticEvent, useEffect, useRef, useState } from 'react';
import StarIcon from '@mui/icons-material/Star';
import SearchIcon from '@mui/icons-material/Search';
import ListSubheader from '@mui/material/ListSubheader';
import List from '@mui/material/List';
import ListItemButton from '@mui/material/ListItemButton';
import ListItemIcon from '@mui/material/ListItemIcon';
import ListItemText from '@mui/material/ListItemText';
import FolderIcon from '@mui/icons-material/Folder';
import ChevronRightRoundedIcon from '@mui/icons-material/ChevronRightRounded';
import CloseIcon from '@mui/icons-material/Close';
import DoubleArrowRoundedIcon from '@mui/icons-material/DoubleArrowRounded';
import MoreVertOutlinedIcon from '@mui/icons-material/MoreVertOutlined';
import AddIcon from '@mui/icons-material/Add';
import CheckRoundedIcon from '@mui/icons-material/CheckRounded';
import { createFolder } from "../../../api/folders";
import { TransitionGroup } from "react-transition-group";
import EditOutlinedIcon from '@mui/icons-material/EditOutlined';
import ShortcutRoundedIcon from '@mui/icons-material/ShortcutRounded';
import FolderView from "./FolderView";
import { AppContext } from "src/types/AppContext";
import { Folder } from "@shared/types/Folder";

type FolderStates = {
  [key: number]: boolean;
};

export default function FoldersPage() {
  const {
    folders,
    isAdmin,
    foldersMap,
  } = useOutletContext<AppContext>();

  const [keyFolders, setKeyFolders] = useState<Folder[]>([]);
  const [otherFolders, setOtherFolders] = useState<Folder[]>([]);
  const [openStates, setOpenStates] = useState<{ [key: number]: boolean; }>({});
  const [renderReady, setRenderReady] = useState(false);

  const [searchParams, setSearchParams] = useSearchParams({ folderQ: '' });

  const viewingFolderId = Number(searchParams.get('viewingFolderId')) || null;
  const query = searchParams.get('folderQ') || '';

  const setViewingFolderId = (id: number) => {
    setSearchParams(prev => {
      prev.set('viewingFolderId', String(id));
      return prev;
    }, { replace: true });
  };

  const setQuery = (value: string) => {
    setSearchParams(prev => {
      prev.set('folderQ', value);
      return prev;
    }, { replace: true });
  };

  const prevFolders = useRef(folders);
  const prevQuery = useRef(query);

  const openAllAncestors = (folderId: number, statesObj: FolderStates) => {
    let currentFolder = foldersMap[folderId];

    while (currentFolder && currentFolder.parent_id) {
      statesObj[currentFolder.parent_id] = true;
      currentFolder = foldersMap[currentFolder.parent_id];
    }

    statesObj[currentFolder.id] = true;
  };

  const openAllChildren = (folderId: number, statesObj: FolderStates) => {
    const childrenToOpen: number[] = [];

    const findChildren = (parentId: number) => {
      folders.forEach((folder) => {
        if (folder.parent_id === parentId) {
          childrenToOpen.push(folder.id);
          findChildren(folder.id);
        }
      });
    };

    findChildren(folderId);

    childrenToOpen.forEach((childId) => {
      statesObj[childId] = true;
    });

    if (childrenToOpen.length) {
      statesObj[folderId] = true;
    }
  };

  const handleExpandAll = () => {
    const tempOpenStates = {};

    const lcQuery = query?.toLowerCase();

    folders.forEach((folder) => {
      if (lcQuery && folder.name.toLowerCase().includes(lcQuery)) {
        openAllChildren(folder.id, tempOpenStates);
      } else {
        openAllAncestors(folder.id, tempOpenStates);
      }
    });

    setOpenStates(tempOpenStates);
  };

  const handleCollapseAll = () => {
    setOpenStates({});
  };

  useEffect(() => {
    let foldersUpdated = false;
    let queryUpdated = query !== prevQuery.current;

    if (!queryUpdated) {
      foldersUpdated = JSON.stringify(prevFolders.current) !== JSON.stringify(folders);
    } else {
      prevQuery.current = query;
    }

    if ((queryUpdated || foldersUpdated) || !renderReady) {
      const tempOpenStates: FolderStates = {};
      let filteredKeyFolders: Folder[] = [];
      let filteredOtherFolders: Folder[] = [];

      const lcQuery = query?.toLowerCase();

      folders.forEach(folder => {
        if (!folder.parent_id) {
          if (folder.is_key_folder) {
            filteredKeyFolders.push(folder);
          } else {
            filteredOtherFolders.push(folder);
          }
        }
      });

      if (lcQuery) {
        folders.forEach((folder) => {
          if (folder.name.toLowerCase().includes(lcQuery)) {
            openAllAncestors(folder.id, tempOpenStates);
          }
        });

        filteredKeyFolders = filteredKeyFolders.filter((folder) => {
          return (
            tempOpenStates[folder.id]
          );
        });

        filteredOtherFolders = filteredOtherFolders.filter((folder) => {
          return (
            tempOpenStates[folder.id]
          );
        });
      }

      setKeyFolders(filteredKeyFolders);
      setOtherFolders(filteredOtherFolders);

      if ((!foldersUpdated && lcQuery)) {
        setOpenStates(tempOpenStates);
      } else {
        prevFolders.current = folders;
      }

      if (!renderReady) {
        setRenderReady(true);
      }
    }
  }, [query, folders]);

  return (
    <>
      {
        !renderReady ?
          <Grid item xs={12} style={{ transition: 'all 250ms' }}>
            <Paper className="flex-ac">
              Loading folders ...
              <CircularProgress size={30} sx={{ mx: 2, my: 4 }} />
            </Paper>
          </Grid>
          :
          <>
            <FolderList
              allFolders={folders}
              keyFolders={keyFolders}
              otherFolders={otherFolders}
              openStates={openStates}
              setOpenStates={setOpenStates}
              query={query.toLowerCase()}
              handleExpandAll={handleExpandAll}
              handleCollapseAll={handleCollapseAll}
              setQuery={setQuery}
              isAdmin={isAdmin}
              viewingFolderId={viewingFolderId}
              setViewingFolderId={setViewingFolderId}
            />
            {
              viewingFolderId ?
                <FolderView
                  folderId={viewingFolderId}
                />
                :
                null
            }
          </>
      }
    </>
  );
};

type FolderListProps = {
  keyFolders: Folder[],
  otherFolders: Folder[];
  allFolders: Folder[];
  openStates: FolderStates,
  setOpenStates: React.Dispatch<React.SetStateAction<{
    [key: number]: boolean;
  }>>,
  query: string,
  handleExpandAll: () => void,
  handleCollapseAll: () => void,
  setQuery: (value: string) => void,
  viewingFolderId: number | null,
  setViewingFolderId: (value: number) => void;
  isAdmin: boolean;
};

function FolderList(props: FolderListProps) {
  const {
    keyFolders,
    otherFolders,
    allFolders,
    openStates,
    setOpenStates,
    query,
    handleExpandAll,
    handleCollapseAll,
    setQuery,
    isAdmin,
    viewingFolderId,
    setViewingFolderId,
  } = props;

  const {
    openDrawer,
    openSnackBar,
    engagement,
    setFolders,
    openModal
  } = useOutletContext<AppContext>();

  const [selectedFolderId, setSelectedFolderId] = useState<number | null>(null);
  const [dblClickFlag, setDblClickFlag] = useState(false);
  const [addFolderPopup, setAddFolderPopup] = useState<Element | null>(null);
  const [moreMenuAnchor, setMoreMenuAnchor] = useState<Element | null>(null);
  const [editFolderId, setEditFolderId] = useState<number | null>(null);
  const [addingFolder, setAddingFolder] = useState(false);

  const addFolderPopupOpen = Boolean(addFolderPopup);
  const moreMenuOpen = Boolean(moreMenuAnchor);

  const newFolderName = useRef<HTMLInputElement>();

  const handleFolderClick = (folderId: number, hasNestedFolders: boolean) => {
    if (hasNestedFolders) {
      if (selectedFolderId === folderId && dblClickFlag === true) {
        clearTimeout(window.updateOpenFolderStates);
        setViewingFolderId(folderId);
        return;
      }

      setDblClickFlag(true);
      setSelectedFolderId(folderId);

      window.updateOpenFolderStates = setTimeout(() => {
        setOpenStates(prevOpenStates => ({
          ...prevOpenStates,
          [folderId]: !prevOpenStates[folderId],
        }));
      }, 200);

      setTimeout(() => {
        setDblClickFlag(false);
      }, 200);
    } else {
      setSelectedFolderId(folderId);
      setViewingFolderId(folderId);
    }
  };

  const handleAddNewFolderClick = (e: SyntheticEvent, folderId: number) => {
    e.stopPropagation();
    setEditFolderId(folderId);
    setAddFolderPopup(e.currentTarget);
  };

  const handleMoreMenuClick = (e: SyntheticEvent, folderId: number) => {
    e.stopPropagation();
    setEditFolderId(folderId);
    setMoreMenuAnchor(e.currentTarget);
  };

  const handleAddFolder = async () => {
    const folderName = newFolderName.current?.value;

    if (!folderName) {
      openSnackBar("Folder name can't be blank.");
      return;
    }

    if (!editFolderId) {
      openSnackBar("No folder is selected.");
      return;
    }

    setAddingFolder(true);

    try {
      const { folder, message } = await createFolder({
        name: folderName,
        engagementId: engagement.id,
        parentId: editFolderId
      });

      if (folder) {
        openSnackBar('Folder added.', 'success');
        setFolders(folders => [...folders, folder]);
        setAddingFolder(false);
        setAddFolderPopup(null);
      } else {
        openSnackBar(message, 'error');
        setAddingFolder(false);
      }
    } catch (error: unknown) {
      if (error instanceof Error) {
        openSnackBar(error.message, 'error');
        setAddingFolder(false);
      }
    }
  };

  const handleEditFolderClick = () => {
    openDrawer('folder', { folderProps: { id: editFolderId } });
    setMoreMenuAnchor(null);
  };

  const handleMoveFolderClick = () => {
    openModal('move-folder', { moveFolderId: editFolderId });
    setMoreMenuAnchor(null);
  };

  const handleDeleteFolderClick = () => {
    openModal('delete-folder', { folderId: editFolderId });
    setMoreMenuAnchor(null);
  };

  const gridWidth = viewingFolderId ? 2.5 : 12;

  return (
    <Grid item xs={gridWidth} style={{ transition: 'flex-basis 250ms, max-width 250ms' }}>
      <Paper sx={{ px: 0, py: 1.5 }}>
        <Box className="flex-ac" px={viewingFolderId ? 1.5 : 3} gap={3} flexWrap='wrap'>
          <Tooltip title="New folder" placement="bottom-end">
            <Box
              hidden={!isAdmin}
              className="new-folder-btn"
              onClick={() => openDrawer('folder')}>
              {
                document.body.className.includes('dark') ?
                  <img
                    alt=""
                    height={40}
                    src="data:image/png;base64,"></img>
                  :
                  <img
                    width={40}
                    alt=""
                    src="data:image/png;base64," />
              }

            </Box>
          </Tooltip>
          <ExpandCollapseButtonGroup
            handleExpandAll={handleExpandAll}
            handleCollapseAll={handleCollapseAll}
          />
          {
            !viewingFolderId ?
              <TextField
                style={{ transition: 'all 1s' }}
                onChange={e => setQuery(e.target.value)}
                variant="standard"
                size="small"
                value={query}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon fontSize="small" />
                    </InputAdornment>
                  ),
                  endAdornment: (
                    <InputAdornment position="start" style={{ visibility: query ? 'visible' : 'hidden' }}>
                      <Tooltip title='Clear'>
                        <IconButton size="small" onClick={() => setQuery('')}>
                          <CloseIcon fontSize="small" />
                        </IconButton>
                      </Tooltip>
                    </InputAdornment>
                  )
                }}
                placeholder="Search"
              />
              : null
          }
        </Box>
        {
          viewingFolderId ?
            <Box p={1} ml={1}>
              <TextField
                style={{ transition: 'all 1s' }}
                onChange={e => setQuery(e.target.value)}
                variant="standard"
                size="small"
                value={query}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <Tooltip title='Clear'>
                        <IconButton size="small" onClick={() => setQuery('')}>
                          <SearchIcon fontSize="small" />
                        </IconButton>
                      </Tooltip>
                    </InputAdornment>
                  ),
                  endAdornment: (
                    <InputAdornment position="start" style={{ visibility: query ? 'visible' : 'hidden' }}>
                      <Tooltip title='Clear'>
                        <IconButton size="small" onClick={() => setQuery('')}>
                          <CloseIcon fontSize="small" />
                        </IconButton>
                      </Tooltip>
                    </InputAdornment>
                  )
                }}
                placeholder="Search"
              />
            </Box> :
            null
        }

        <Divider sx={{ mt: 1 }} />

        <List
          className="folders-list"
          dense
          component="nav"
          subheader={
            <ListSubheader className="flex-ac" disableSticky>
              <StarIcon htmlColor="gold" style={{ marginRight: '2px' }} />  Key Folders
            </ListSubheader>
          }>
          <TransitionGroup>
            {
              keyFolders.map(folder => {
                return (
                  <Collapse key={folder.id}>
                    <FolderListItem
                      name={folder.name}
                      id={folder.id}
                      selectedFolderId={selectedFolderId}
                      handleFolderClick={handleFolderClick}
                      allFolders={allFolders}
                      openStates={openStates}
                      query={query}
                      viewingFolderId={viewingFolderId}
                      handleAddNewFolderClick={handleAddNewFolderClick}
                      handleMoreMenuClick={handleMoreMenuClick}
                    />
                  </Collapse>
                );
              })
            }
          </TransitionGroup>
          <ListSubheader className="flex-ac" disableSticky>
            Other Folders
          </ListSubheader>
          <TransitionGroup>
            {
              otherFolders.map(folder => {
                return (
                  <Collapse key={folder.id}>
                    <FolderListItem
                      name={folder.name}
                      id={folder.id}
                      selectedFolderId={selectedFolderId}
                      handleFolderClick={handleFolderClick}
                      allFolders={allFolders}
                      openStates={openStates}
                      query={query}
                      viewingFolderId={viewingFolderId}
                      handleAddNewFolderClick={handleAddNewFolderClick}
                      handleMoreMenuClick={handleMoreMenuClick}
                    />
                  </Collapse>
                );
              })
            }
          </TransitionGroup>
        </List>
      </Paper>

      <Menu
        anchorEl={addFolderPopup}
        open={addFolderPopupOpen}
        transformOrigin={{
          vertical: 'top',
          horizontal: 'center',
        }}
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'center',
        }}
        onClose={() => setAddFolderPopup(null)}>
        <TextField
          disabled={addingFolder}
          onKeyDown={e => e.key === 'Enter' ? handleAddFolder() : null}
          autoFocus
          size="small"
          placeholder="Folder name"
          style={{ margin: '0 10px' }}
          variant="standard"
          inputRef={newFolderName}
          inputProps={{
            style: {
              fontSize: '14px'
            }
          }}
          InputProps={{
            endAdornment:
              <InputAdornment position="end">
                <Tooltip title="Save">
                  <span>
                    <IconButton
                      disabled={addingFolder}
                      size="small"
                      onClick={handleAddFolder}>
                      {
                        addingFolder ?
                          <CircularProgress size={15} />
                          :
                          <CheckRoundedIcon
                            color="success"
                            fontSize="small" />
                      }
                    </IconButton>
                  </span>
                </Tooltip>
              </InputAdornment>
          }}
        />
      </Menu>

      <Menu
        className="folder-actions-menu"
        anchorEl={moreMenuAnchor}
        open={moreMenuOpen}
        transformOrigin={{
          vertical: 'top',
          horizontal: 'center',
        }}
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'center',
        }}
        onClose={() => setMoreMenuAnchor(null)}>
        <MenuItem dense onClick={handleEditFolderClick}>
          <EditOutlinedIcon fontSize="small" />
          Edit folder
        </MenuItem>
        <MenuItem dense onClick={handleMoveFolderClick}>
          <ShortcutRoundedIcon fontSize="small" />
          Move folder
        </MenuItem>
        <Divider className="m0" />
        <MenuItem dense onClick={handleDeleteFolderClick}>
          <ListItemText inset color="error">
            <Typography color="error" component="span">
              Delete folder
            </Typography>
          </ListItemText>
        </MenuItem>
      </Menu>
    </Grid>
  );
}

function renderNestedFolders(folders: Folder[], parentFolderId: number, handleFolderClick: (folderId: number, hasNestedFolders: boolean) => void, openStates: FolderStates, selectedFolderId: number | null, query: string, viewingFolderId: number | null, handleAddNewFolderClick: (e: SyntheticEvent, folderId: number) => void, handleMoreMenuClick: (e: SyntheticEvent, folderId: number) => void, depth = 1) {
  depth++;
  const nestedFolders = folders.filter(folder => folder.parent_id === parentFolderId);

  const indent = viewingFolderId ? (`${24 * depth}px`) : (`${36 * depth}px`);
  const itemTextStyle = { flexGrow: viewingFolderId ? 1 : 0, flexBasis: viewingFolderId ? 'auto' : '20%' };

  return (
    <TransitionGroup>
      {
        nestedFolders.map(folder => {
          const hasNestedFolders = folders.some(subfolder => subfolder.parent_id === folder.id);

          return (
            <Collapse key={folder.id}>
              <ListItemButton
                className="folder-listitem"
                disableRipple
                selected={selectedFolderId === folder.id}
                sx={{ pl: indent }}
                onClick={() => handleFolderClick(folder.id, hasNestedFolders)}>
                <ListItemIcon style={{ position: 'relative', minWidth: 34 }}>
                  {
                    hasNestedFolders ?
                      <ChevronRightRoundedIcon
                        style={{ transform: openStates[folder.id] ? 'rotate(90deg)' : 'rotate(0deg)' }}
                        className="toggle-icon" />
                      : null
                  }
                  <FolderIcon className="folder-icon" />
                </ListItemIcon>
                <ListItemText
                  style={itemTextStyle}
                  primary={renderFolderName(query, folder.name)} />
                <Box className="folder-actions">
                  <Tooltip title="Add folder">
                    <IconButton size="small" onClick={e => handleAddNewFolderClick(e, folder.id)}>
                      <AddIcon fontSize="small" />
                    </IconButton>
                  </Tooltip>
                  <Tooltip title="More">
                    <IconButton size="small" onClick={e => handleMoreMenuClick(e, folder.id)}>
                      <MoreVertOutlinedIcon fontSize="small" />
                    </IconButton>
                  </Tooltip>
                </Box>
              </ListItemButton>
              {
                hasNestedFolders ?
                  <Collapse in={openStates[folder.id]} timeout="auto">
                    {renderNestedFolders(folders, folder.id, handleFolderClick, openStates, selectedFolderId, query, viewingFolderId, handleAddNewFolderClick, handleMoreMenuClick, depth)}
                  </Collapse> : null
              }
            </Collapse>
          );
        })
      }
    </TransitionGroup>
  );
}

function renderFolderName(lcQuery: string, name: string) {
  if (lcQuery) {
    const regex = new RegExp(`(${lcQuery.replace(/[-/\\^$*+?.()|[\]{}]/g, '\\$&')})`, 'i');
    const parts = name.split(regex);

    return (
      <span>
        {parts.map((part, index) => (
          regex.test(part) ? (
            <span key={index} className='highlighted-text'>{part}</span>
          ) : (
            part
          )
        ))}
      </span>
    );
  } else {
    return name;
  }
};

type FolderListItemProps = {
  name: string,
  id: number,
  selectedFolderId: number | null,
  handleFolderClick: (folderId: number, hasNestedFolders: boolean) => void,
  allFolders: Folder[],
  openStates: FolderStates,
  query: string,
  viewingFolderId: number | null,
  handleAddNewFolderClick: (e: SyntheticEvent, folderId: number) => void,
  handleMoreMenuClick: (e: SyntheticEvent, folderId: number) => void;
};

export function FolderListItem(props: FolderListItemProps) {
  const {
    name,
    id,
    selectedFolderId,
    handleFolderClick,
    allFolders,
    openStates,
    query,
    viewingFolderId,
    handleAddNewFolderClick,
    handleMoreMenuClick
  } = props;

  const hasNestedFolders = allFolders.some(subfolder => subfolder.parent_id === id);

  return (
    <>
      <ListItemButton
        className="folder-listitem"
        selected={selectedFolderId === id}
        disableRipple
        sx={{ pl: viewingFolderId ? '32px' : '40px', transition: 'padding 250ms' }}
        onClick={() => handleFolderClick(id, hasNestedFolders)}>
        <ListItemIcon style={{ position: 'relative', minWidth: 34 }}>
          {
            hasNestedFolders ?
              <ChevronRightRoundedIcon
                style={{
                  transform: openStates[id] ? 'rotate(90deg)' : 'rotate(0deg)'
                }}
                className="toggle-icon" />
              : null
          }
          <FolderIcon className="folder-icon" />
        </ListItemIcon>
        <ListItemText
          primary={renderFolderName(query, name)}
          style={{ flexGrow: viewingFolderId ? 1 : 0, flexBasis: viewingFolderId ? 'auto' : '20%' }}
        />

        <Box className="folder-actions">
          <Tooltip title="Add folder">
            <IconButton
              size="small"
              onClick={e => handleAddNewFolderClick(e, id)}>
              <AddIcon fontSize="small" />
            </IconButton>
          </Tooltip>
          <Tooltip title="More">
            <IconButton
              onClick={e => handleMoreMenuClick(e, id)}
              size="small">
              <MoreVertOutlinedIcon fontSize="small" />
            </IconButton>
          </Tooltip>
        </Box>
      </ListItemButton>
      {
        hasNestedFolders ?
          <Collapse in={openStates[id]} timeout="auto">
            {renderNestedFolders(allFolders, id, handleFolderClick, openStates, selectedFolderId, query, viewingFolderId, handleAddNewFolderClick, handleMoreMenuClick)}
          </Collapse>
          : null
      }
    </>
  );
}

type ExpandCollapseButtonGroupProps = {
  handleExpandAll: () => void,
  handleCollapseAll: () => void;
};

function ExpandCollapseButtonGroup({ handleExpandAll, handleCollapseAll }: ExpandCollapseButtonGroupProps) {
  return (
    <ButtonGroup variant="outlined" style={{ marginLeft: -10 }}>
      <Tooltip title="Expand all">
        <Button
          onClick={handleExpandAll}>
          <DoubleArrowRoundedIcon
            style={{ transform: 'rotate(90deg)', fontSize: 14 }}
          />
        </Button>
      </Tooltip>
      <Tooltip title="Collapse all">
        <Button
          onClick={handleCollapseAll}>
          <DoubleArrowRoundedIcon
            style={{ transform: 'rotate(-90deg)', fontSize: 14 }}
          />
        </Button>
      </Tooltip>
    </ButtonGroup>
  );
}